#!/usr/bin/env python3
from __future__ import annotations

import base64
import hashlib
import os
import shutil
import struct
import sys
import tempfile
import traceback
import zlib
from pathlib import Path

PATCHER_VERSION = 2
STEAM_VERSION = 45
GOG_VERSION = 45
DESIGNATION = f"v{PATCHER_VERSION}Pv{STEAM_VERSION}Sv{GOG_VERSION}G"
EDITION_VERSIONS = {"Steam": STEAM_VERSION, "GOG": GOG_VERSION}

STEAM_RETAIL_EXE = "ca1c4766900feb867372e0e2e87eb5adb92ca26ee537598a034ed7be1313d93c"
STEAM_RETAIL_DATA0 = "0debd38c1560830486d8f7bdecf3806324e4f6357f1353ea0058b47bdfe8aa3b"
STEAM_BUILD15_EXE = "b468197ddcba6547db8dda2efc3cd29f524f57992756aa813142b5531b2fd78d"
STEAM_BUILD15_DATA0 = "ffa18821657e8f25063897a28730a03fb962abf22d572fb3d4fdd83772db0eab"
STEAM_TARGET_EXE = "125a3b088e502049913d7a6d20f0ad76d7a0e5fe086d14bb257c4d0798ca5844"
STEAM_TARGET_DATA0 = "55cab794160a244ef3db3abfa0e3beb23643ebb20c3d95831d0c553905372744"

GOG_RETAIL_EXE = "c061b0cd177c04e9ae30bdd5b8693caff2c2474b8f48f8d9c7e2bcd05f817708"
GOG_RETAIL_DATA0 = "7c5b83bc26a703abe4a55d460b73d0248168d16e7b2998d0d6e8a45244a03e60"
GOG_TARGET_EXE = "c0cc2bcb760e5b6fff9e6f0ab5e4ccf3acec5859f08f11a77339f551501a45e4"
GOG_TARGET_DATA0 = "601fdb9311635352af663b7c10959b263f5650a463f4dc20f1b54b390273d62b"

PATCH_B64 = {
    'steam_retail_exe.cojdp1.zlib.b64': '',
    'steam_retail_data0.cojdp1.zlib.b64': '',
    'steam_build15_exe.cojdp1.zlib.b64': '',
    'steam_build15_data0.cojdp1.zlib.b64': '',
    'gog_retail_exe.cojdp1.zlib.b64': '',
    'gog_retail_data0.cojdp1.zlib.b64': '',
}

PATCH_FILES = {
    "steam_retail": ("steam_retail_exe.cojdp1.zlib.b64", "steam_retail_data0.cojdp1.zlib.b64"),
    "steam_build15": ("steam_build15_exe.cojdp1.zlib.b64", "steam_build15_data0.cojdp1.zlib.b64"),
    "gog_retail": ("gog_retail_exe.cojdp1.zlib.b64", "gog_retail_data0.cojdp1.zlib.b64"),
}


def app_dir() -> Path:
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent
    return Path.cwd().resolve()


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def find_game_files(root: Path) -> tuple[Path, Path]:
    exe = root / "CoJGunslinger.exe"
    candidates = [root / "coj4" / "Data0.pak", root / "Data0.pak"]
    data0 = next((p for p in candidates if p.is_file()), candidates[0])
    if not exe.is_file():
        raise FileNotFoundError("CoJGunslinger.exe not found next to the patcher.")
    if not data0.is_file():
        raise FileNotFoundError("Data0.pak not found (expected coj4\\Data0.pak or Data0.pak).")
    return exe, data0


def backup_once(path: Path) -> Path:
    backup = path.with_name(path.name + ".Backup")
    if not backup.exists():
        shutil.copy2(path, backup)
    return backup


def load_direct_patch(filename: str) -> bytes:
    try:
        return base64.b64decode(PATCH_B64[filename])
    except KeyError as exc:
        raise ValueError(f"Missing embedded direct patch: {filename}") from exc


def apply_cojdp1(source: bytes, compressed_patch: bytes) -> bytes:
    raw = zlib.decompress(compressed_patch)
    if raw[:6] != b"COJDP1":
        raise ValueError("Invalid direct patch format")

    pos = 6
    source_size, target_size = struct.unpack_from("<QQ", raw, pos)
    pos += 16
    source_sha = raw[pos:pos + 32]
    pos += 32
    target_sha = raw[pos:pos + 32]
    pos += 32
    _block_size, count = struct.unpack_from("<II", raw, pos)
    pos += 8

    if len(source) != source_size or hashlib.sha256(source).digest() != source_sha:
        raise ValueError("Direct patch source verification failed")

    out = bytearray()
    for _ in range(count):
        if pos >= len(raw):
            raise ValueError("Truncated direct patch instruction stream")
        opcode = raw[pos]
        pos += 1
        if opcode == 0:
            offset, length = struct.unpack_from("<QI", raw, pos)
            pos += 12
            if offset + length > len(source):
                raise ValueError("Direct patch copy range outside source")
            out.extend(source[offset:offset + length])
        elif opcode == 1:
            length = struct.unpack_from("<I", raw, pos)[0]
            pos += 4
            if pos + length > len(raw):
                raise ValueError("Truncated direct patch literal")
            out.extend(raw[pos:pos + length])
            pos += length
        else:
            raise ValueError("Unknown direct patch opcode")

    if pos != len(raw):
        raise ValueError("Unexpected trailing direct patch data")
    result = bytes(out)
    if len(result) != target_size or hashlib.sha256(result).digest() != target_sha:
        raise ValueError("Direct patch target verification failed")
    return result


def rebuild_pair(source_kind: str, exe: Path, data0: Path, temp: Path) -> tuple[Path, Path]:
    out_dir = temp / "build45"
    out_dir.mkdir(parents=True, exist_ok=True)
    exe_patch_name, data_patch_name = PATCH_FILES[source_kind]

    exe_target = apply_cojdp1(exe.read_bytes(), load_direct_patch(exe_patch_name))
    data_target = apply_cojdp1(data0.read_bytes(), load_direct_patch(data_patch_name))

    out_exe = out_dir / "CoJGunslinger.exe"
    out_data = out_dir / "Data0.pak"
    out_exe.write_bytes(exe_target)
    out_data.write_bytes(data_target)
    return out_exe, out_data


def verify_target(edition: str, exe: Path, data0: Path) -> None:
    hashes = (sha256_file(exe), sha256_file(data0))
    expected = {
        "Steam": (STEAM_TARGET_EXE, STEAM_TARGET_DATA0),
        "GOG": (GOG_TARGET_EXE, GOG_TARGET_DATA0),
    }[edition]
    if hashes != expected:
        raise ValueError(
            f"Final {edition} v{EDITION_VERSIONS[edition]} verification failed.\n"
            f"EXE:   {hashes[0]}\nData0: {hashes[1]}"
        )


def pause() -> None:
    if getattr(sys, "frozen", False):
        try:
            input("\nPress Enter to close...")
        except EOFError:
            pass


def main() -> int:
    print("=" * 68)
    print(" Call of Juarez: Gunslinger - Enhanced PC Patch")
    print(f" {DESIGNATION} | Patcher v{PATCHER_VERSION} | Steam v{STEAM_VERSION} | GOG v{GOG_VERSION}")
    print("=" * 68)
    try:
        root = app_dir()
        exe, data0 = find_game_files(root)
        print(f"[OK] Game directory: {root}")
        print("[ .. ] Detecting edition and verifying game files...")
        eh, dh = sha256_file(exe), sha256_file(data0)

        if (eh, dh) == (STEAM_TARGET_EXE, STEAM_TARGET_DATA0):
            print(f"[OK] Steam v{STEAM_VERSION} is already installed. Nothing to do.")
            return 0
        if (eh, dh) == (GOG_TARGET_EXE, GOG_TARGET_DATA0):
            print(f"[OK] GOG v{GOG_VERSION} is already installed. Nothing to do.")
            return 0

        if (eh, dh) == (STEAM_RETAIL_EXE, STEAM_RETAIL_DATA0):
            edition, source_kind = "Steam", "steam_retail"
            print("[OK] Original Steam files detected.")
        elif (eh, dh) == (STEAM_BUILD15_EXE, STEAM_BUILD15_DATA0):
            edition, source_kind = "Steam", "steam_build15"
            print("[OK] Steam Enhanced PC Patch Build 15 detected.")
        elif (eh, dh) == (GOG_RETAIL_EXE, GOG_RETAIL_DATA0):
            edition, source_kind = "GOG", "gog_retail"
            print("[OK] Original GOG files detected.")
        else:
            print("[ERROR] Unsupported or mixed game files.")
            print("        No files have been modified.")
            print(f"        EXE SHA-256:   {eh}")
            print(f"        Data0 SHA-256: {dh}")
            return 2

        eb, db = backup_once(exe), backup_once(data0)
        print(f"[OK] Edition: {edition}")
        print(f"[OK] Backup: {eb.name}")
        print(f"[OK] Backup: {db.name}")

        with tempfile.TemporaryDirectory(prefix="coj_patch_", dir=str(root)) as td:
            temp = Path(td)
            print(f"[ .. ] Building {edition} v{EDITION_VERSIONS[edition]} with patcher v{PATCHER_VERSION}...")
            new_exe, new_data = rebuild_pair(source_kind, exe, data0, temp)

            print("[ .. ] Verifying patched files before installation...")
            verify_target(edition, new_exe, new_data)
            print(f"[OK] {edition} v{EDITION_VERSIONS[edition]} hashes verified.")

            staged_exe = exe.with_name(exe.name + ".PatchNew")
            staged_data = data0.with_name(data0.name + ".PatchNew")
            try:
                shutil.copy2(new_exe, staged_exe)
                shutil.copy2(new_data, staged_data)
                verify_target(edition, staged_exe, staged_data)

                rollback_exe = temp / "rollback_CoJGunslinger.exe"
                rollback_data = temp / "rollback_Data0.pak"
                shutil.copy2(exe, rollback_exe)
                shutil.copy2(data0, rollback_data)
                try:
                    os.replace(staged_exe, exe)
                    os.replace(staged_data, data0)
                except Exception:
                    shutil.copy2(rollback_exe, exe)
                    shutil.copy2(rollback_data, data0)
                    raise
            finally:
                staged_exe.unlink(missing_ok=True)
                staged_data.unlink(missing_ok=True)

        verify_target(edition, exe, data0)
        print("=" * 68)
        print(f"[SUCCESS] {DESIGNATION} installed for {edition} v{EDITION_VERSIONS[edition]}.")
        print("          Final SHA-256 verification passed.")
        print("=" * 68)
        return 0

    except Exception as exc:
        print("\n[ERROR]", exc)
        print("No unverified patched output was intentionally installed.")
        if os.environ.get("COJ_PATCHER_DEBUG") == "1":
            traceback.print_exc()
        return 1
    finally:
        pause()


if __name__ == "__main__":
    raise SystemExit(main())